/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic in,
    output logic out
);
    typedef enum logic [1:0] {A, B, C, D} state_t;
    state_t state_r, state_n;

    always_comb begin
        state_n = A;
        case (state_r)
            A: if (in) state_n = B; else state_n = A;
            B: if (in) state_n = B; else state_n = C;
            C: if (in) state_n = D; else state_n = A;
            D: if (in) state_n = B; else state_n = C;
            default: state_n = A;
        endcase
    end

    always_ff @(posedge clk or posedge areset) begin
        if (areset) state_r <= A;
        else        state_r <= state_n;
    end

    assign out = (state_r == D);
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0, areset = 0, in = 0;
    wire out;
    integer model = 0;
    integer checks = 0;
    integer transitions [0:3][0:1];
    TopModule dut (.clk(clk), .areset(areset), .in(in), .out(out));
    always #5 clk = ~clk;

    task automatic check_output;
        begin
            if (out !== (model == 3))
                $fatal(1, "Output mismatch: state=%0d out=%b", model, out);
            checks = checks + 1;
        end
    endtask

    task automatic reset_fsm;
        begin
            @(negedge clk);
            #1 areset = 1;
            model = 0;
            #1 check_output();
            @(negedge clk);
            #1 areset = 0;
            #1 check_output();
        end
    endtask

    task automatic step(input bit value);
        integer previous;
        begin
            @(negedge clk);
            in = value;
            #1 check_output(); // Moore output cannot depend on new input.
            previous = model;
            case (model)
                0: if (value) model = 1; else model = 0;
                1: if (value) model = 1; else model = 2;
                2: if (value) model = 3; else model = 0;
                3: if (value) model = 1; else model = 2;
            endcase
            transitions[previous][value] = transitions[previous][value] + 1;
            @(posedge clk);
            #1 check_output();
        end
    endtask

    initial begin
        for (integer s = 0; s < 4; s = s + 1)
            for (integer b = 0; b < 2; b = b + 1)
                transitions[s][b] = 0;
        for (integer pattern = 0; pattern < 256; pattern = pattern + 1) begin
            reset_fsm();
            for (integer k = 0; k < 8; k = k + 1)
                step((pattern >> k) & 1);
        end
        reset_fsm();
        step(1); step(0); step(1); // Reach D before asynchronous reset.
        reset_fsm();
        step(0);
        for (integer s = 0; s < 4; s = s + 1)
            for (integer b = 0; b < 2; b = b + 1)
                if (transitions[s][b] == 0) $fatal(1, "Missing transition coverage");
        $display("PASS: %0d output checks; all eight transitions covered", checks);
        $finish;
    end
    initial begin
        #100000;
        $fatal(1, "Development test timeout");
    end
endmodule
EOF
timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
cat dev_compile.log
printf '"'compile_exit_code=%s\\n' \""'$compile_status" > dev_status.log
if [ "$compile_status" -eq 0 ]; then
    timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    sim_status=$?
    printf '"'simulation_exit_code=%s\\n' \""'$sim_status" >> dev_status.log
    cat dev_simulation.log
fi'

